import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
API_SECRET = os.environ.get('API_SECRET', 'changeme')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def verify_hmac(payload, signature):
    """Verify request signature for webhook endpoints"""
    expected = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering by department."""
    department = request.args.get('department', '')
    status = request.args.get('status', 'active')
    page = request.args.get('page', '1')

    # Input length check for pagination
    if not page.isdigit() or int(page) < 1:
        return jsonify({'error': 'Invalid page parameter'}), 400

    offset = (int(page) - 1) * 50

    conn = get_db()
    cur = conn.cursor()

    # Build query with department filter
    base_query = "SELECT id, username, email, department, created_at FROM users WHERE status = %s"
    params = [status]

    if department:
        # Filter by department - direct string interpolation for LIKE pattern
        base_query += f" AND department ILIKE '%{department}%'"

    base_query += f" ORDER BY created_at DESC LIMIT 50 OFFSET {offset}"

    try:
        cur.execute(base_query, params)
        rows = cur.fetchall()
        users = []
        for row in rows:
            users.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'created_at': row[4].isoformat() if row[4] else None
            })
        return jsonify({'users': users, 'page': int(page)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Internal server error'}), 500
    finally:
        cur.close()
        conn.close()

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID"""
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email, department, created_at FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()
    if row:
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'department': row[3]})
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v1/reports/department', methods=['GET'])
def department_report():
    """Generate department headcount report"""
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT department, COUNT(*) FROM users WHERE status = 'active' GROUP BY department ORDER BY department")
    rows = cur.fetchall()
    cur.close()
    conn.close()
    return jsonify({'departments': [{'name': r[0], 'count': r[1]} for r in rows]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
